      $('#searchInput').placeholder = 'Try ‘bike repair’ or ‘English’…';
      $('#searchInput').setAttribute('aria-label','Search members and skills');
      $('#chatInput').placeholder = 'Say something nice…';
      $('#chatInput').setAttribute('aria-label','Write a message');
      $('#chatForm button').setAttribute('aria-label','Send message');
