    if(language==='fr') for(const [local,english] of Object.entries({'conversation en anglais':'english conversation','reparation de velos':'bicycle repair','entretien de velos':'bike maintenance','creation de sites web':'web design','anglais':'english','suedois':'swedish','jardinage':'gardening','cuisine':'cooking','programmation':'programming','photographie':'photography','menuiserie':'woodworking','velos':'bicycles','velo':'bike'})) text=text.replaceAll(local,english);
